function tokenize(s){ return (String(s||'').toLowerCase().match(/[a-z一-龥]+/g)||[]); }
function tfidf(docs){ docs=(docs||[]).filter(function(d){return d && String(d).trim();});
  var N=docs.length; if(N===0) return {error:'请提供文档'};
  var df={}; var tfs=docs.map(function(d){ var toks=tokenize(d); var f={}; for(var i=0;i<toks.length;i++) f[toks[i]]=(f[toks[i]]||0)+1;
    var uniq={}; for(var k in f) uniq[k]=true; for(var k in uniq) df[k]=(df[k]||0)+1;
    var max=0; for(var k in f) if(f[k]>max) max=f[k]; var tf={}; for(var k in f) tf[k]=f[k]/(max||1); return tf; });
  var idf={}; for(var k in df) idf[k]=Math.round((Math.log((N+1)/(df[k]+1))+1)*1000)/1000;
  var out=docs.map(function(_,i){ var r={}; for(var k in tfs[i]) r[k]=Math.round(tfs[i][k]*idf[k]*1000)/1000; return r; });
  return {docCount:N, idf:idf, tfidf:out}; }
var EXPORTS={tfidf:tfidf, tokenize:tokenize};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
